from collections import defaultdict, deque


class RateLimiter:
    def __init__(self, limit: int, window: int, mode: str = "fixed"):
        if mode not in ("fixed", "sliding"):
            raise ValueError(f"unknown mode {mode!r}")
        self.limit = limit
        self.window = window
        self.mode = mode
        self._limits: dict[str, int] = {}
        self._fixed: dict[str, tuple[int, int]] = {}
        self._log: dict[str, deque[int]] = defaultdict(deque)

    def set_limit(self, user_id: str, limit: int) -> None:
        self._limits[user_id] = limit

    def _allow_fixed(self, user_id: str, limit: int, now: int) -> bool:
        window_id = now // self.window
        current, count = self._fixed.get(user_id, (window_id, 0))
        if current != window_id:
            count = 0
        if count >= limit:
            self._fixed[user_id] = (window_id, count)
            return False
        self._fixed[user_id] = (window_id, count + 1)
        return True

    def _allow_sliding(self, user_id: str, limit: int, now: int) -> bool:
        log = self._log[user_id]
        while log and log[0] <= now - self.window:
            log.popleft()
        if len(log) >= limit:
            return False
        log.append(now)
        return True

    def allow(self, now: int, user_id: str = "") -> bool:
        limit = self._limits.get(user_id, self.limit)
        if self.mode == "sliding":
            return self._allow_sliding(user_id, limit, now)
        return self._allow_fixed(user_id, limit, now)

