from collections import defaultdict, deque
from fractions import Fraction


class FixedWindow:
    def __init__(self, window: int):
        self.window = window
        self.state: dict[str, tuple[int, int]] = {}

    def allow(self, user_id: str, limit: int, now: int) -> bool:
        window_id = now // self.window
        current, count = self.state.get(user_id, (window_id, 0))
        if current != window_id:
            count = 0
        if count >= limit:
            self.state[user_id] = (window_id, count)
            return False
        self.state[user_id] = (window_id, count + 1)
        return True


class SlidingLog:
    def __init__(self, window: int):
        self.window = window
        self.logs: dict[str, deque[int]] = defaultdict(deque)

    def allow(self, user_id: str, limit: int, now: int) -> bool:
        log = self.logs[user_id]
        while log and log[0] <= now - self.window:
            log.popleft()
        if len(log) >= limit:
            return False
        log.append(now)
        return True


class TokenBucket:
    def __init__(self, window: int, burst: int):
        self.window = window
        self.burst = burst
        # user -> (tokens, last_refill_time); exact arithmetic avoids float drift
        self.buckets: dict[str, tuple[Fraction, int]] = {}

    def allow(self, user_id: str, limit: int, now: int) -> bool:
        capacity = limit + self.burst
        tokens, last = self.buckets.get(user_id, (Fraction(capacity), now))
        tokens = min(Fraction(capacity), tokens + Fraction(limit * (now - last), self.window))
        if tokens >= 1:
            self.buckets[user_id] = (tokens - 1, now)
            return True
        self.buckets[user_id] = (tokens, now)
        return False


class RateLimiter:
    def __init__(self, limit: int, window: int, mode: str = "fixed", burst: int = 0):
        strategies = {
            "fixed": lambda: FixedWindow(window),
            "sliding": lambda: SlidingLog(window),
            "token_bucket": lambda: TokenBucket(window, burst),
        }
        if mode not in strategies:
            raise ValueError(f"unknown mode {mode!r}")
        self.limit = limit
        self.window = window
        self.mode = mode
        self._limits: dict[str, int] = {}
        self._strategy = strategies[mode]()

    def set_limit(self, user_id: str, limit: int) -> None:
        self._limits[user_id] = limit

    def allow(self, now: int, user_id: str = "") -> bool:
        return self._strategy.allow(user_id, self._limits.get(user_id, self.limit), now)
